import itertools

def solve():
    def get_all_triangles(m):
        return list(itertools.combinations(range(m), 3))

    def get_all_edges(m):
        return list(itertools.combinations(range(m), 2))

    def check(m):
        edges = get_all_edges(m)
        num_edges = len(edges)
        num_colors = m

        # Try to find a coloring. This is a search problem.
        # We can use backtracking.
        color_assignment = [-1] * num_edges

        def is_valid(edge_idx, color):
            u, v = edges[edge_idx]
            # Proper coloring: edges incident to same vertex must have different colors
            for i in range(edge_idx):
                u_i, v_i = edges[i]
                if (u == u_i or u == v_i or v == u_i or v == v_i) and color_assignment[i] == color:
                    return False
            return True

        def backtrack(edge_idx):
            if edge_idx == num_edges:
                # All edges colored. Now check if every 3-subset of colors is represented.
                triangles = get_all_triangles(m)
                found_subsets = set()
                for t in triangles:
                    # Find the colors of the 3 edges of the triangle
                    c1 = -1
                    c2 = -1
                    c3 = -1
                    # edges of triangle (t[0], t[1], t[2])
                    for i, edge in enumerate(edges):
                        if (edge[0] == t[0] and edge[1] == t[1]) or (edge[0] == t[1] and edge[1] == t[0]):
                            c1 = color_assignment[i]
                        elif (edge[0] == t[1] and edge[1] == t[2]) or (edge[0] == t[2] and edge[1] == t[1]):
                            c2 = color_assignment[i]
                        elif (edge[0] == t[0] and edge[1] == t[2]) or (edge[0] == t[2] and edge[1] == t[0]):
                            c3 = color_assignment[i]

                    if len({c1, c2, c3}) == 3:
                        found_subsets.add(tuple(sorted((c1, c2, c3))))

                return len(found_subsets) == len(list(itertools.combinations(range(num_colors), 3)))

            for c in range(num_colors):
                if is_valid(edge_idx, c):
                    color_assignment[edge_idx] = c
                    if backtrack(edge_idx + 1):
                        return True
                    color_assignment[edge_idx] = -1
            return False

        return backtrack(0)

    for m in range(3, 8):
        print(f"m={m}: {check(m)}")

