import itertools

def check_m(m):
    # We need to check if there exists a proper edge coloring of K_m using m colors
    # such that every 3-subset of colors forms a triangle.
    # This is equivalent to saying every triangle is rainbow AND each 3-subset is used once.

    # Proper edge coloring: every vertex has distinct colors on its edges.
    # Each vertex misses at least one color.
    # Since there are m vertices and m colors, and m(m-1)/2 edges,
    # the sum of missing colors is m*m - m(m-1) = m.
    # Thus, each vertex misses exactly one color.

    edges = list(itertools.combinations(range(m), 2))
    num_edges = len(edges)

    def backtrack(edge_idx, color_assignment):
        if edge_idx == num_edges:
            # All edges colored. Check if all 3-subsets of colors are represented.
            triangles = list(itertools.combinations(range(m), 3))
            found_subsets = set()
            for t in triangles:
                c = []
                for i, edge in enumerate(edges):
                    if (edge[0] == t[0] and edge[1] == t[1]) or (edge[0] == t[1] and edge[1] == t[0]):
                        c.append(color_assignment[i])
                    elif (edge[0] == t[1] and edge[1] == t[2]) or (edge[0] == t[2] and edge[1] == t[1]):
                        c.append(color_assignment[i])
                    elif (edge[0] == t[0] and edge[1] == t[2]) or (edge[0] == t[2] and edge[1] == t[0]):
                        c.append(color_assignment[i])
                found_subsets.add(tuple(sorted(c)))
            return len(found_subsets) == len(list(itertools.combinations(range(m), 3)))

        u, v = edges[edge_idx]
        # Find colors already used at u and v
        used_colors = set()
        for i in range(edge_idx):
            u_i, v_i = edges[i]
            if u == u_i or u == v_i:
                used_colors.add(color_assignment[i])
            if v == u_i or v == v_i:
                used_colors.add(color_assignment[i])

        for c in range(m):
            if c not in used_colors:
                color_assignment[edge_idx] = c
                if backtrack(edge_idx + 1, color_assignment):
                    return True
                color_assignment[edge_idx] = -1
        return False

    return backtrack(0, [-1] * num_edges)

print(f"m=4: {check_m(4)}")
print(f"m=6: {check_m(6)}")
